CREATE VIRTUAL TABLE rt USING rtree(id, minx, maxx, miny, maxy); CREATE TABLE mytable(fid INTEGER PRIMARY KEY, geom BLOB); CREATE TRIGGER tr1 AFTER UPDATE OF geom ON mytable WHEN OLD.fid = NEW.fid AND NEW.geom IS NULL BEGIN DELETE FROM rt WHERE id = OLD.fid; END; INSERT INTO mytable VALUES(1, X'abcd');